// Candidate-facing acknowledgement, branded from the approval row's cfg. Same design system as the card and digest.
// Runs after the page has been served, so the row comes from Decide, not from the input item.
const row = $('Decide').first().json;
const c = row.candidate || {};
const job = row.job || {};
const cfg = row.cfg || {};
const agency = cfg.agency_name || 'the team';
const primary = cfg.brand_primary || '#0ea672';
const ink = cfg.brand_ink || '#111827';
const consultant = cfg.consultant_name || '';
const website = cfg.agency_website || '';
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const first = String(c.full_name || '').trim().split(/\s+/)[0] || 'there';
const band = String(c.band || '').toUpperCase();
const strong = band === 'A' || band === 'B';
const title = job.title || 'the role';
const email = String(c.email || '').trim();
const fallback = cfg.fallback_email || cfg.consultant_email || 'owner@example.com';
const to = (email.includes('@') && !email.toLowerCase().endsWith('example.com')) ? email : fallback;
const paras = strong
  ? [`Thanks for applying for the ${title} role. We've read your CV and we'd like to talk.`, `${consultant ? consultant : 'One of our consultants'} will be in touch within 24 hours to arrange a call. If you'd rather pick a time now, reply to this email with what suits you.`]
  : [`Thanks for applying for the ${title} role. Your CV is with the consultant handling it.`, `We're reviewing applications over the next few days and will come back to you either way. If anything changes in the meantime, reply to this email and it will reach the right person.`];
const font = "-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif";
const html = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(agency)}</title></head>
<body style="margin:0;padding:0;background:#f3f4f6;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f3f4f6;">
<tr><td align="center" style="padding:24px 12px 32px;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border:1px solid #e5e7eb;border-radius:12px;overflow:hidden;">
  <tr><td style="height:4px;background:${primary};font-size:0;line-height:0;">&nbsp;</td></tr>
  <tr><td style="padding:24px 28px 0;font:700 15px/1 ${font};color:${ink};">${esc(agency)}</td></tr>
  <tr><td style="padding:24px 28px 0;font:16px/1.6 ${font};color:${ink};">Hi ${esc(first)},</td></tr>
  ${paras.map(p => `<tr><td style="padding:14px 28px 0;font:16px/1.6 ${font};color:${ink};">${esc(p)}</td></tr>`).join('')}
  <tr><td style="padding:22px 28px 0;font:16px/1.6 ${font};color:${ink};">Kind regards</td></tr>
  <tr><td style="padding:2px 28px 26px;font:600 16px/1.6 ${font};color:${ink};">${esc(consultant || agency)}${consultant ? `<div style="font:400 14px/1.5 ${font};color:#6b7280;">${esc(agency)}</div>` : ''}</td></tr>
  <tr><td style="padding:14px 28px;border-top:1px solid #e5e7eb;font:12px/1.6 ${font};color:#9ca3af;">${esc(agency)}${website ? ` &middot; <a href="${esc(website)}" style="color:#9ca3af;">${esc(website.replace(/^https?:\/\//, ''))}</a>` : ''}<br>You're receiving this because you applied for a role with us. Reply to this email to reach the consultant handling your application.</td></tr>
</table>
</td></tr></table></body></html>`;
return [{ json: { to, subject: `Your application for ${title} - ${agency}`, html, agency, reply_to: cfg.consultant_email || fallback } }];

// One branded page for every outcome. Reads the Decide row directly because three paths converge here.
const r = $('Decide').first().json || {};
const o = r.outcome || 'invalid';
const c = r.candidate || {};
const cfg = r.cfg || {};
const first = String(c.full_name || '').trim().split(/\s+/)[0] || 'The candidate';
const agency = cfg.agency_name || 'OpsAutomated';
const ats = cfg.ats_label || 'the ATS';
const primary = cfg.brand_primary || '#0ea672';
const band = String(c.band || '').toUpperCase();
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const when = iso => { const t = new Date(iso); return isNaN(t) ? '' : t.toLocaleString('en-GB', { weekday: 'short', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit', timeZone: 'Europe/London' }); };
const ok = { bg: '#d1fae5', fg: '#065f46', glyph: '&#10003;' }, hold = { bg: '#e5e7eb', fg: '#374151', glyph: '&#8230;' }, warn = { bg: '#fff7ed', fg: '#9a3412', glyph: '!' };
let tone = ok, title = '', body = '', hint = 'You can close this tab.';
switch (o) {
  case 'sent':
    title = `${first} has been acknowledged`;
    body = `The Band ${band} reply is on its way from ${agency}, with your address as reply-to. ${ats} and the screening log are up to date.`;
    break;
  case 'changed_to_sent':
    title = `${first} has been acknowledged`;
    body = `You'd put ${first} on hold earlier. The Band ${band} reply has gone now, from ${agency}, with your address as reply-to.`;
    break;
  case 'held':
    tone = hold; title = `${first} is on hold`;
    body = `Nothing has been sent. ${first} stays filed in ${ats} and will show as on hold in tomorrow's digest.`;
    hint = `Changed your mind? Reply on the card still works.`;
    break;
  case 'already_held':
    tone = hold; title = `${first} is already on hold`;
    body = `Nothing has changed. ${first} is filed in ${ats} and will show as on hold in tomorrow's digest.`;
    hint = `Reply on the card still works if you'd like to send the acknowledgement.`;
    break;
  case 'already_sent':
    title = `${first} was acknowledged${r.sent_at ? ' on ' + when(r.sent_at) : ''}`;
    body = `The reply has already gone, so there's nothing more to send. ${first} is filed in ${ats}.`;
    break;
  default:
    tone = warn; title = `This link isn't valid`;
    body = `It may be from an old card. Open the latest card in your inbox, or find the candidate in ${ats}.`;
}
const footer = cfg.agency_name ? `Run for ${esc(agency)} by OpsAutomated.` : 'OpsAutomated';
const font = "-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif";
const html = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(agency)}</title></head><body style="margin:0;background:#f3f4f6;font-family:${font};"><div style="height:4px;background:${primary};"></div><div style="max-width:520px;margin:48px auto;padding:0 20px;"><div style="font:700 15px/1 ${font};color:#111827;">${esc(agency)}</div><div style="margin-top:28px;background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:28px 24px;"><div style="width:44px;height:44px;border-radius:999px;background:${tone.bg};color:${tone.fg};font:700 22px/44px ${font};text-align:center;">${tone.glyph}</div><h1 style="margin:18px 0 0;font:700 22px/1.25 ${font};color:#111827;letter-spacing:-.01em;">${esc(title)}</h1><p style="margin:12px 0 0;font:15px/1.55 ${font};color:#374151;">${esc(body)}</p><p style="margin:20px 0 0;font:13px/1.5 ${font};color:#9ca3af;">${esc(hint)}</p></div><div style="margin-top:16px;font:12px/1.6 ${font};color:#9ca3af;">${footer}</div></div></body></html>`;
return [{ json: { html, outcome: o } }];
